'use strict';

/* ==== src/background/auth.js ====================================== */
/**
 * OAuth. No client secret in this file, or anywhere.
 *
 * ============================================================================
 * WHY THIS USES THE IMPLICIT FLOW AND NOT PKCE
 * ============================================================================
 *
 * This file previously used authorization-code + PKCE, which is the textbook
 * answer for a public client and is what I argued for at length. It cannot
 * work here, and the reason is a Google-specific constraint, not a design
 * mistake in the abstract:
 *
 *   - Google's token endpoint requires `client_secret` for
 *     `grant_type=authorization_code` on a **Web application** client. PKCE
 *     does not exempt you. The response is
 *     `400 invalid_request / "client_secret is missing."`
 *
 *   - The obvious fix -- switch the client to type **Chrome Extension**, which
 *     is a public client -- does not work either. Google's own extensions
 *     DevRel has confirmed that Chrome Extension clients accept only
 *     `getAuthToken`-style flows, and their allowed redirect URIs are "very
 *     strict": a `https://<id>.chromiumapp.org/` redirect is rejected.
 *
 *   - `chrome.identity.getAuthToken` would sidestep all of it, but it is
 *     Chrome-only. It does not work in Brave, Edge or Firefox, and Brave is
 *     what this is actually being used in.
 *
 * So every code-exchange route demands a secret we refuse to ship. This is the
 * same wall v1 hit -- and v1's answer was to hardcode the secret, which is how
 * it ended up leaked in a public repo.
 *
 * The way out is to not exchange anything. `response_type=token` returns the
 * access token directly in the redirect fragment. There is no token endpoint
 * call, so there is nothing to authenticate with a secret.
 *
 * WHAT THIS COSTS, STATED PLAINLY
 *   - Access tokens last one hour.
 *   - There is no refresh token. Implicit flow does not issue them.
 *
 * WHAT MAKES IT ACCEPTABLE
 *   Re-auth is silent. `launchWebAuthFlow({interactive: false})` with
 *   `prompt=none` mints a fresh token without any UI for as long as the user's
 *   Google session cookie is alive, which for a browser people read mail in is
 *   effectively always. The user sees a consent screen once. If the silent
 *   path fails, we fall back to one interactive prompt.
 *
 *   Security-wise this is a fair trade: a one-hour token that cannot be
 *   refreshed is a strictly smaller prize for an attacker than a refresh token
 *   that grants `gmail.modify` indefinitely.
 *
 * ============================================================================
 * SCOPES
 * ============================================================================
 *
 * `gmail.modify` covers read, label, archive, star and delete-to-trash. We do
 * NOT request `gmail.send` or full `https://mail.google.com/` -- this build
 * does not compose, and asking for send access we never use is both a review
 * risk and a straightforward breach of least privilege.
 */

const AUTH_ENDPOINT = 'https://accounts.google.com/o/oauth2/v2/auth';
const REVOKE_ENDPOINT = 'https://oauth2.googleapis.com/revoke';

const SCOPES = [
  'https://www.googleapis.com/auth/gmail.modify',
].join(' ');

/**
 * Set by the user in Options.
 *
 * NOT hardcoded. Every install can use its own Google Cloud project, which
 * means no shared credential to leak and no single client ID whose revocation
 * breaks everybody.
 */
async function getClientId() {
  const { clientId } = await chrome.storage.local.get('clientId');
  if (!clientId) {
    throw new Error(
      'No OAuth client ID configured. Open the extension options and paste ' +
        'the client ID from your Google Cloud project.'
    );
  }
  return clientId;
}

function base64url(bytes) {
  let s = '';
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

/**
 * Build the authorization URL.
 *
 * `response_type=token` is the whole point: the access token comes back in the
 * redirect fragment and there is no exchange to authenticate.
 *
 * @param {string} clientId
 * @param {string} redirectUri
 * @param {string} state
 * @param {boolean} silent  adds `prompt=none` for background renewal
 */
function authUrl(clientId, redirectUri, state, silent) {
  const params = new URLSearchParams({
    client_id: clientId,
    redirect_uri: redirectUri,
    response_type: 'token',
    scope: SCOPES,
    state,
    include_granted_scopes: 'true',
  });
  // prompt=none means "renew if you already can, otherwise fail immediately
  // rather than showing me a window". That is what makes silent renewal
  // possible without ever flashing UI at the user.
  if (silent) params.set('prompt', 'none');
  else params.set('prompt', 'consent');
  return `${AUTH_ENDPOINT}?${params}`;
}

/** Random URL-safe token, used for the `state` parameter. */
function randomState() {
  return base64url(crypto.getRandomValues(new Uint8Array(16)));
}

/**
 * Run one authorization round trip.
 *
 * @param {boolean} interactive  false = silent renewal, no UI ever
 * @returns {Promise<{access_token:string, expires_in:number}>}
 */
async function authorize(interactive) {
  const clientId = await getClientId();
  const redirectUri = chrome.identity.getRedirectURL();
  const state = randomState();

  let responseUrl;
  try {
    responseUrl = await chrome.identity.launchWebAuthFlow({
      url: authUrl(clientId, redirectUri, state, !interactive),
      interactive,
    });
  } catch (err) {
    // A silent attempt failing is normal and expected -- it just means the
    // Google session needs a real prompt. Only surface interactive failures.
    if (!interactive) throw new Error('SILENT_FAILED');
    throw new Error(friendlyAuthError(err?.message || String(err)));
  }

  if (!responseUrl) {
    throw new Error(interactive ? 'Sign-in was cancelled.' : 'SILENT_FAILED');
  }

  // Implicit flow returns everything in the FRAGMENT, not the query string.
  const url = new URL(responseUrl);
  const frag = new URLSearchParams(url.hash.replace(/^#/, ''));
  const query = url.searchParams;

  const error = frag.get('error') || query.get('error');
  if (error) {
    if (!interactive) throw new Error('SILENT_FAILED');
    throw new Error(friendlyAuthError(error, frag.get('error_description')));
  }

  // Verify state before trusting anything else in the response.
  if (frag.get('state') !== state) {
    throw new Error('OAuth state mismatch -- sign-in aborted.');
  }

  const accessToken = frag.get('access_token');
  if (!accessToken) {
    if (!interactive) throw new Error('SILENT_FAILED');
    throw new Error(
      'Google returned no access token.\n\n' +
        'FIX: the OAuth client must be of type "Web application", and its ' +
        'Authorized redirect URIs must include exactly:\n' +
        redirectUri
    );
  }

  return {
    access_token: accessToken,
    expires_in: Number(frag.get('expires_in')) || 3600,
  };
}

/** Interactive sign-in. Persists the token. */
async function signIn() {
  /*
   * A new sign-in supersedes anything in flight too -- including a silent
   * renewal for the PREVIOUS account. Without this, switching accounts could
   * let the old account's renewal overwrite the new account's token, which is
   * worse than the sign-out case: the user ends up reading someone else's
   * mailbox with no indication anything went wrong.
   */
  sessionEpoch++;
  inFlight = null;

  // Captured BEFORE the await, or the comparison below is against a value
  // read after any concurrent change and can never differ.
  const epoch = sessionEpoch;
  const tok = await authorize(true);
  // If a signOut landed while the consent screen was open, do not persist.
  if (epoch !== sessionEpoch) throw new Error('NOT_SIGNED_IN');
  await persist(tok);
  // Remember that consent was granted, so getToken() knows silent renewal is
  // worth attempting. Implicit flow gives us no refresh token to test for.
  await chrome.storage.local.set({ authorized: true });
  return tok;
}

/**
 * Translate Google's terse OAuth errors into something actionable.
 *
 * The previous version reported `Token exchange failed (400).` and discarded
 * the body, which is the only field that distinguishes several unrelated
 * setup mistakes. That cost a full debugging round trip, so every known code
 * now carries its remedy.
 */
function friendlyAuthError(code, description) {
  const HELP = {
    invalid_client:
      'The OAuth client rejected this request.\n\n' +
      'FIX: in Google Cloud Console the client must be type "Web application", ' +
      'and its Authorized redirect URIs must contain the URI shown on the ' +
      'extension options page.',
    invalid_request:
      'Google rejected the shape of the request.\n\n' +
      'FIX: check the client ID is pasted in full, and that the redirect URI ' +
      'on the options page is registered on the client.',
    redirect_uri_mismatch:
      'The redirect URI is not registered on this OAuth client.\n\n' +
      'FIX: copy the URI from the extension options page into the client\'s ' +
      'Authorized redirect URIs. It must match exactly, trailing slash included.',
    access_denied:
      'Consent was refused, or this account is not allowed to use the app.\n\n' +
      'FIX: add your BITS address under OAuth consent screen -> Test users.',
    admin_policy_enforced:
      'Your Google Workspace admin blocks this app.\n\n' +
      'FIX: the BITS domain restricts third-party access to Gmail; an admin ' +
      'must allow-list the client ID.',
    org_internal:
      'This OAuth client is restricted to another organisation.\n\n' +
      'FIX: set the consent screen to External, or use a client from a project ' +
      'in the same organisation as the signing-in account.',
  };
  const help = HELP[code];
  const lead = `Google rejected the sign-in: ${code}${description ? ` (${description})` : ''}`;
  return help ? `${lead}\n\n${help}` : lead;
}

async function persist(tok) {
  await chrome.storage.local.set({
    accessToken: tok.access_token,
    // Renew 5 minutes early. Implicit tokens cannot be refreshed on demand,
    // so a wider margin avoids a request racing the expiry mid-sync.
    expiresAt: Date.now() + (tok.expires_in ?? 3600) * 1000 - 300_000,
  });
}

/**
 * A valid access token, renewing silently if needed.
 *
 * Concurrent callers share one in-flight renewal. A sync burst issues many
 * requests at once, and firing a dozen simultaneous auth flows would be both
 * slow and rate-limited.
 */
let inFlight = null;

/**
 * Session generation.
 *
 * THIS FIXES A REAL SECURITY DEFECT. `signOut()` cleared storage, but a silent
 * renewal already in flight would call `persist()` AFTERWARDS and write a
 * fresh, live access token back -- so signing out during a renewal left the
 * user believing they were signed out while a working credential sat in
 * storage. Reproduced: sign out 10ms into a 60ms renewal, and `accessToken`
 * came back as a valid token.
 *
 * Clearing storage is not enough on its own because it cannot reach work that
 * has already started. The epoch is the missing piece: every operation that
 * WRITES credentials captures it first and refuses to commit if it has moved.
 *
 * A boolean "signing out" flag would not do -- sign-out completes, and a
 * renewal that started before it must stay invalid forever after, not just
 * during the sign-out itself.
 */
let sessionEpoch = 0;
async function getToken() {
  const s = await chrome.storage.local.get(['accessToken', 'expiresAt', 'authorized']);

  if (s.accessToken && s.expiresAt && Date.now() < s.expiresAt) {
    return s.accessToken;
  }
  if (!s.authorized) throw new Error('NOT_SIGNED_IN');

  if (inFlight) return inFlight;
  inFlight = renew().finally(() => {
    inFlight = null;
  });
  return inFlight;
}

/**
 * Mint a fresh token without showing anything.
 *
 * Works while the browser still holds a Google session cookie, which for a
 * browser someone reads mail in is effectively always. When it does fail we
 * clear the flag so the UI prompts rather than retrying forever.
 */
async function renew() {
  const epoch = sessionEpoch;
  try {
    const tok = await authorize(false);
    // The user may have signed out while this was in flight. Persisting now
    // would resurrect the session they just ended.
    if (epoch !== sessionEpoch) throw new Error('NOT_SIGNED_IN');
    await persist(tok);
    return tok.access_token;
  } catch (err) {
    // Do NOT clear storage for a superseded renewal: sign-out has already
    // cleared it, and a sign-IN may since have populated it afresh. Wiping
    // here would sign the user back out immediately after they signed in.
    if (epoch !== sessionEpoch) throw new Error('NOT_SIGNED_IN');
    await chrome.storage.local.remove(['accessToken', 'expiresAt', 'authorized']);
    throw new Error('NOT_SIGNED_IN');
  }
}
async function signOut() {
  // Invalidate any renewal already in flight BEFORE doing anything else, so
  // it cannot commit a token after this returns. See `sessionEpoch`.
  sessionEpoch++;
  inFlight = null;

  const { accessToken } = await chrome.storage.local.get('accessToken');

  // Revoke server-side, not just locally. The implicit flow issues no refresh
  // token, so the access token IS the whole grant -- revoking it ends access
  // rather than merely forgetting it. v1 cleared storage only, leaving a live
  // credential standing on Google's side.
  if (accessToken) {
    await fetch(`${REVOKE_ENDPOINT}?token=${encodeURIComponent(accessToken)}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    }).catch(() => {
      /* offline; the local removal below still happens */
    });
  }

  // `authorized` must go, or getToken() would keep attempting silent renewal
  // for an account the user just signed out of. historyId goes too: applying
  // one account's deltas to the next would be silent corruption.
  await chrome.storage.local.remove([
    'accessToken',
    'expiresAt',
    'authorized',
    'historyId',
  ]);
}

/**
 * Has the user granted consent?
 *
 * Keyed on the `authorized` flag rather than on a stored token, because an
 * implicit token expires hourly and its absence means "needs renewal", not
 * "signed out". Conflating the two would show the sign-in gate every hour.
 */
async function isSignedIn() {
  const { authorized } = await chrome.storage.local.get('authorized');
  return Boolean(authorized);
}


/* ==== src/background/gmail.js ===================================== */
/**
 * Gmail REST layer. Lives in the service worker so the access token never
 * enters a document that renders untrusted mail HTML.
 *
 * WHY A REAL MULTIPART BATCH
 * --------------------------
 * Fetching 200 message headers one request at a time is 200 TLS round trips
 * and 200 chances to hit a per-request quota. Gmail's /batch endpoint takes up
 * to 100 sub-requests in ONE HTTP request. The old version used it too; this
 * is the one thing it got right about the network layer and it is carried over.
 *
 * We ask for `format=metadata` with an explicit header allow-list. That is a
 * fraction of the bytes of `format=full` and it is everything the list view
 * needs. Bodies are fetched lazily, one message at a time, only when the user
 * actually opens something.
 */

const BASE = 'https://gmail.googleapis.com/gmail/v1/users/me';
const BATCH_URL = 'https://gmail.googleapis.com/batch/gmail/v1';

/** Headers we need for the list view. Anything else is wasted bandwidth. */
const META_HEADERS = ['From', 'Subject', 'Date', 'List-Unsubscribe'];

/** Gmail's own limit. Do not raise it; the endpoint rejects >100. */
const BATCH_SIZE = 100;

async function authHeaders(extra = {}) {
  const token = await getToken();
  return { Authorization: `Bearer ${token}`, ...extra };
}

/**
 * Statuses worth trying again.
 *
 * 429 is the important one and it is NOT an error condition here: Gmail
 * rate-limits per user, and a 100-message batch is a burst by definition, so a
 * healthy sync of a busy inbox produces these routinely. Treating one as fatal
 * showed the user `Gmail 429 /messages` and stopped the sync, and their only
 * recourse was Refresh, which reissued the same burst.
 *
 * 403 is deliberately NOT here. Gmail returns 403 both for `rateLimitExceeded`
 * (retryable) and for insufficient scope (never retryable), and retrying a
 * permissions failure three times just delays a clear error. It is
 * distinguished by body text below.
 */
const RETRYABLE = new Set([429, 500, 502, 503, 504]);

/** Cap on attempts, including the first. Keep small: the user is waiting. */
const MAX_ATTEMPTS = 3;

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/**
 * How long to wait before attempt N (1-indexed).
 *
 * Honours `Retry-After` when Google sends it -- guessing when we have been told
 * is how you get rate-limited harder. Otherwise exponential with jitter; the
 * jitter matters because several parallel batch requests will otherwise all
 * wake at the same instant and re-collide.
 */
function backoffMs(attempt, res) {
  const header = res?.headers?.get?.('Retry-After');
  if (header) {
    const secs = Number(header);
    if (Number.isFinite(secs)) return Math.min(secs * 1000, 30_000);
    const when = Date.parse(header);
    if (!Number.isNaN(when)) return Math.max(0, Math.min(when - Date.now(), 30_000));
  }
  const base = 500 * 2 ** (attempt - 1); // 500, 1000, 2000
  return base + Math.random() * 250;
}

/** True for a 403 that is a quota problem rather than a permissions problem. */
function isQuota403(body) {
  return /rateLimitExceeded|userRateLimitExceeded|quotaExceeded/i.test(body);
}

/**
 * Fetch with bounded retry. Shared by `api()` and the batch endpoint so both
 * behave identically under load.
 *
 * Returns the successful Response. Throws with the last status on give-up.
 */
async function fetchRetrying(url, init, label) {
  let lastErr;
  for (let attempt = 1; attempt <= MAX_ATTEMPTS; attempt++) {
    let res;
    try {
      res = await fetch(url, init);
    } catch (err) {
      // Network-level failure (offline, DNS, connection reset). Retryable.
      lastErr = new Error(`Network error on ${label}: ${err.message}`);
      if (attempt === MAX_ATTEMPTS) break;
      await sleep(backoffMs(attempt, null));
      continue;
    }

    if (res.ok) return res;

    const body = await res.text().catch(() => '');
    const retryable = RETRYABLE.has(res.status) || (res.status === 403 && isQuota403(body));
    lastErr = new Error(`Gmail ${res.status} ${label} ${body.slice(0, 200)}`);

    if (!retryable || attempt === MAX_ATTEMPTS) break;
    await sleep(backoffMs(attempt, res));
  }
  throw lastErr;
}

/** Single authenticated call. `path` is relative to /users/me. */
async function api(path, init = {}) {
  // The token is resolved once, outside the retry loop: getToken() already
  // single-flights refreshes, and an access token cannot expire inside the
  // ~3.5s worst-case retry window (it is refreshed 60s early).
  const headers = await authHeaders(init.headers || {});
  const res = await fetchRetrying(`${BASE}${path}`, { ...init, headers }, path);
  if (res.status === 204) return null;
  return res.json();
}

/**
 * One page of message ids.
 * Returns { ids, nextPageToken }.
 */
async function listIds({ q = '', labelIds = ['INBOX'], max = 100, pageToken = '' } = {}) {
  const params = new URLSearchParams();
  params.set('maxResults', String(Math.min(max, 500)));
  for (const l of labelIds) params.append('labelIds', l);
  if (q) params.set('q', q);
  if (pageToken) params.set('pageToken', pageToken);
  const data = await api(`/messages?${params}`);
  return {
    ids: (data.messages || []).map((m) => m.id),
    nextPageToken: data.nextPageToken || '',
  };
}

/**
 * Metadata for up to BATCH_SIZE ids in ONE request.
 * Returns an array of normalised message records (see `normalise`).
 * Sub-requests that fail are dropped, not thrown -- one dead message must not
 * kill a sync of a hundred good ones.
 */
async function batchMetadata(ids) {
  if (ids.length === 0) return [];
  if (ids.length > BATCH_SIZE) throw new Error(`batchMetadata: ${ids.length} > ${BATCH_SIZE}`);

  const boundary = `bmm_${Math.random().toString(36).slice(2)}_${Date.now()}`;
  const qs = new URLSearchParams();
  qs.set('format', 'metadata');
  for (const h of META_HEADERS) qs.append('metadataHeaders', h);

  const body =
    ids
      .map(
        (id, i) =>
          `--${boundary}\r\n` +
          `Content-Type: application/http\r\n` +
          `Content-ID: <bmm-${i}>\r\n\r\n` +
          `GET /gmail/v1/users/me/messages/${encodeURIComponent(id)}?${qs}\r\n\r\n`
      )
      .join('') + `--${boundary}--\r\n`;

  // Same retry policy as api(). The batch endpoint is the single most likely
  // request to be rate-limited, because it is 100 sub-requests at once.
  const res = await fetchRetrying(
    BATCH_URL,
    {
      method: 'POST',
      headers: await authHeaders({ 'Content-Type': `multipart/mixed; boundary=${boundary}` }),
      body,
    },
    '/batch'
  );
  const text = await res.text();
  return parseBatch(text).map(normalise).filter(Boolean);
}

/**
 * Parse a multipart/mixed batch response into JSON objects.
 *
 * Deliberately tolerant: Google has changed the exact header casing and line
 * endings in this response before, and a strict parser silently returns an
 * empty inbox when that happens. We find the JSON payload of each part by
 * looking for the last blank-line separator inside the part.
 */
function parseBatch(text) {
  const m = text.match(/--([^\s-][^\r\n]*?)(?:\r?\n)/);
  if (!m) return [];
  const boundary = m[1].replace(/--$/, '');
  const out = [];
  for (const raw of text.split(`--${boundary}`)) {
    const part = raw.trim();
    if (!part || part === '--') continue;
    // part = <mime headers>\n\n<HTTP status + headers>\n\n<body>
    const chunks = part.split(/\r?\n\r?\n/);
    if (chunks.length < 3) continue;
    const status = chunks[1].split(/\r?\n/)[0] || '';
    if (!/\s2\d\d\s/.test(` ${status} `)) continue; // drop failed sub-requests
    const bodyText = chunks.slice(2).join('\n\n').trim();
    if (!bodyText.startsWith('{')) continue;
    try {
      out.push(JSON.parse(bodyText));
    } catch {
      /* one malformed part must not poison the batch */
    }
  }
  return out;
}

/**
 * Gmail's wire format -> our flat record.
 *
 * Flat on purpose. The old version kept Gmail's nested payload/headers array
 * in the store, which meant every render walked an array of ~20 header objects
 * per message just to find the subject.
 */
function normalise(g) {
  if (!g?.id) return null;

  /*
   * THIS IS THE TRUST BOUNDARY for everything that comes off the network.
   *
   * It used to copy header values through verbatim, which broke two ways:
   *
   *   1. A header with no `name`, or a null entry in the array, threw here
   *      and killed the whole page of messages -- one malformed header meant
   *      an empty inbox.
   *   2. A non-string `value` was passed straight through, so `subject` could
   *      be a number and `from` an object. Downstream, `classify()` calls
   *      `.toLowerCase()` and `buildReply()` calls `.replace()`, both of which
   *      throw on a non-string. Fuzzing found both.
   *
   * Coercing HERE rather than defending in every consumer is the correct
   * layer: there is one place data enters, and dozens that read it. Every
   * field below is guaranteed to be the type its JSDoc claims.
   */
  const h = headerMap(g.payload?.headers);
  const labels = Array.isArray(g.labelIds) ? g.labelIds : [];
  return {
    id: str(g.id),
    threadId: str(g.threadId) || str(g.id),
    from: h.from || '',
    subject: h.subject || '(no subject)',
    snippet: decodeEntities(str(g.snippet)),
    // internalDate is ms-since-epoch as a STRING, and it is authoritative.
    // The Date: header is attacker-controlled and is routinely wrong.
    date: Number(g.internalDate) || Date.parse(h.date) || 0,
    unread: labels.includes('UNREAD'),
    starred: labels.includes('STARRED'),
    important: labels.includes('IMPORTANT'),
    labels,
  };
}

/**
 * Coerce any header/field value to a string.
 *
 * Gmail's API is well behaved, but "well behaved" is not a guarantee we can
 * enforce, and a single unexpected type used to crash the classifier for an
 * entire page of mail. Objects and arrays become '' rather than
 * "[object Object]", which would otherwise become searchable text.
 */
/**
 * Fold a Gmail header array into a lowercase-keyed object.
 *
 * Exported because THREE separate places parsed header arrays by hand
 * (`normalise` here, and `extractBody`'s message and part loops in
 * index.js), and all three used the same `for (const { name, value } of ...)`
 * shape that throws on a header with no `name` or a null entry. Fuzzing found
 * the crash independently in each.
 *
 * One malformed header used to cost an entire page of mail in `normalise`,
 * and a single unreadable message in `extractBody`. Both are now impossible
 * because there is one parser rather than three copies of an assumption.
 */
function headerMap(headers) {
  const out = Object.create(null);
  if (!Array.isArray(headers)) return out;
  for (const entry of headers) {
    const name = entry?.name;
    if (typeof name !== 'string') continue;
    out[name.toLowerCase()] = str(entry.value);
  }
  return out;
}

function str(v) {
  if (typeof v === 'string') return v;
  if (v === null || v === undefined) return '';
  if (typeof v === 'number' || typeof v === 'boolean') return String(v);
  return '';
}

function decodeEntities(s) {
  return s
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&nbsp;/g, ' ');
}

/** Full body for one message, fetched only when the user opens it. */
async function getFull(id) {
  return api(`/messages/${encodeURIComponent(id)}?format=full`);
}

/** Add/remove labels. Used for read, star, archive. */
async function modify(id, addLabelIds = [], removeLabelIds = []) {
  return api(`/messages/${encodeURIComponent(id)}/modify`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ addLabelIds, removeLabelIds }),
  });
}

/** Bulk modify -- one request for up to 1000 ids. */
async function batchModify(ids, addLabelIds = [], removeLabelIds = []) {
  if (!ids.length) return null;
  await api('/messages/batchModify', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ ids, addLabelIds, removeLabelIds }),
  });
  return { ok: true };
}
async function trash(id) {
  return api(`/messages/${encodeURIComponent(id)}/trash`, { method: 'POST' });
}
async function profile() {
  return api('/profile');
}

/**
 * Delta sync. Returns { changes, historyId } or { tooOld: true } when the
 * stored historyId has expired (Gmail keeps ~1 week) and a full resync is
 * required. Callers must handle `tooOld`; the old version did not, which is
 * why it silently stopped updating after a long absence.
 *
 * PAGINATION IS NOT OPTIONAL HERE.
 * The response's `historyId` is the mailbox's CURRENT id, not the id of the
 * last record on this page. So if we read page 1 and then store that value, we
 * have advanced the cursor past pages 2..n without ever reading them, and
 * those changes are unrecoverable. Either we drain every page, or we do not
 * move the cursor at all.
 */
const MAX_HISTORY_PAGES = 10; // 10 * 500 = 5000 records; past that, resync is cheaper
async function history(startHistoryId) {
  const changes = [];
  let pageToken = '';
  let historyId = null;

  for (let page = 0; page < MAX_HISTORY_PAGES; page++) {
    const params = new URLSearchParams({
      startHistoryId: String(startHistoryId),
      maxResults: '500',
    });
    for (const t of ['messageAdded', 'messageDeleted', 'labelAdded', 'labelRemoved']) {
      params.append('historyTypes', t);
    }
    if (pageToken) params.set('pageToken', pageToken);

    let data;
    try {
      data = await api(`/history?${params}`);
    } catch (err) {
      // 404 = the cursor is older than Gmail's retention window.
      if (String(err).includes('404')) return { tooOld: true };
      throw err;
    }

    if (data.history) changes.push(...data.history);
    historyId = data.historyId || historyId;
    pageToken = data.nextPageToken || '';
    if (!pageToken) return { changes, historyId };
  }

  // Still paging after MAX_HISTORY_PAGES. Advancing the cursor now would skip
  // whatever is left, so treat it as a resync instead of losing mail.
  return { tooOld: true };
}


// ============================================================================
// COMPOSE
// ============================================================================

/**
 * RFC 2047 encoded-word, for header values containing non-ASCII.
 *
 * Subject lines carrying a rupee sign or a name with a diacritic are common in
 * BITS mail, and a raw 8-bit byte in a header is a protocol violation that
 * Gmail rejects outright. Base64 is used rather than quoted-printable because
 * it cannot produce a line that needs folding for a realistic subject.
 */
function encodeHeader(value) {
  const s = String(value ?? '');
  // eslint-disable-next-line no-control-regex
  if (/^[\x20-\x7E]*$/.test(s)) return s; // pure ASCII: leave it readable
  const bytes = new TextEncoder().encode(s);
  let bin = '';
  for (const b of bytes) bin += String.fromCharCode(b);
  return `=?UTF-8?B?${btoa(bin)}?=`;
}

/** base64url, which is what the Gmail API wants for a raw RFC 2822 message. */
function b64urlEncode(text) {
  const bytes = new TextEncoder().encode(text);
  let bin = '';
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

/**
 * Build an RFC 2822 message.
 *
 * Deliberately hand-built rather than pulled from a MIME library: the whole
 * extension has zero runtime dependencies, and a correct multipart/alternative
 * for this narrow case is about thirty lines. Anything a library would add
 * beyond that (attachments with content-disposition, nested multiparts) is not
 * something this build sends.
 *
 * @param {{to:string, cc?:string, bcc?:string, subject:string, body:string,
 *   inReplyTo?:string, references?:string, from?:string}} m
 */
function buildMime(m) {
  const boundary = `bmm_${Math.random().toString(36).slice(2)}`;
  const headers = [
    m.from ? `From: ${m.from}` : null,
    `To: ${m.to}`,
    m.cc ? `Cc: ${m.cc}` : null,
    m.bcc ? `Bcc: ${m.bcc}` : null,
    `Subject: ${encodeHeader(m.subject)}`,
    // Threading. Without these two a reply starts a NEW conversation, which is
    // the single most visible way a mail client looks broken.
    m.inReplyTo ? `In-Reply-To: ${m.inReplyTo}` : null,
    m.references ? `References: ${m.references}` : null,
    'MIME-Version: 1.0',
  ].filter(Boolean);

  const plain = m.body;
  const html = plainToHtml(m.body);

  /*
   * The body is always multipart/alternative: a text/plain fallback beside the
   * HTML, so clients that do not render HTML still show something readable.
   */
  const altParts = [
    `--${boundary}`,
    'Content-Type: text/plain; charset="UTF-8"',
    'Content-Transfer-Encoding: 8bit',
    '',
    plain,
    '',
    `--${boundary}`,
    'Content-Type: text/html; charset="UTF-8"',
    'Content-Transfer-Encoding: 8bit',
    '',
    html,
    '',
    `--${boundary}--`,
    '',
  ];

  const files = Array.isArray(m.attachments) ? m.attachments.filter(Boolean) : [];

  /*
   * NO ATTACHMENTS: EMIT EXACTLY WHAT WE ALWAYS DID.
   *
   * Wrapping every message in multipart/mixed "for consistency" would add a
   * layer to the 99% case to serve the 1%, and some clients render the extra
   * nesting badly. The common path is untouched.
   */
  if (!files.length) {
    return [
      ...headers,
      `Content-Type: multipart/alternative; boundary="${boundary}"`,
    ].join('\r\n') + `\r\n\r\n${altParts.join('\r\n')}`;
  }

  /*
   * WITH ATTACHMENTS: multipart/mixed WRAPPING the alternative, not replacing
   * it. Flattening the alternative away would lose the text/plain fallback.
   * The outer boundary must differ from the inner one or a parser cannot tell
   * where the nested part ends.
   */
  const outer = `${boundary}_mixed`;
  const body = [
    `--${outer}`,
    `Content-Type: multipart/alternative; boundary="${boundary}"`,
    '',
    ...altParts,
  ];

  for (const f of files) {
    const name = safeFilename(f.filename);
    body.push(
      `--${outer}`,
      `Content-Type: ${safeHeaderValue(f.mimeType || 'application/octet-stream')}; name="${name}"`,
      `Content-Disposition: attachment; filename="${name}"`,
      'Content-Transfer-Encoding: base64',
      '',
      // Already base64 from the reader; fold to 76 columns as RFC 2045 asks.
      String(f.data || '').replace(/\s+/g, '').replace(/(.{76})/g, '$1\r\n'),
      ''
    );
  }
  body.push(`--${outer}--`, '');

  return [
    ...headers,
    `Content-Type: multipart/mixed; boundary="${outer}"`,
  ].join('\r\n') + `\r\n\r\n${body.join('\r\n')}`;
}

/**
 * Make a filename safe to sit inside a quoted MIME parameter.
 *
 * A filename is ATTACKER-CONTROLLED the moment you forward something. An
 * unescaped `"` closes the parameter early and a CRLF injects an entire new
 * header -- which turns a forward into a header-injection primitive capable of
 * adding a Bcc. Strip the line breaks, strip the quotes, and cap the length.
 */
function safeFilename(name) {
  return String(name || 'attachment')
    .replace(/[\r\n]+/g, ' ')
    .replace(/"/g, '')
    .slice(0, 200)
    .trim() || 'attachment';
}

/** Same rule for any value we interpolate into a header. */
function safeHeaderValue(v) {
  return String(v || '').replace(/[\r\n"]+/g, '').slice(0, 200);
}

/** Minimal, escaped plain-text -> HTML. Never interpolates raw user text. */
function plainToHtml(text) {
  const esc = String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
  return `<div style="white-space:pre-wrap;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Arial,sans-serif">${esc}</div>`;
}

/**
 * Send a message.
 * `threadId` keeps a reply inside its conversation.
 */
async function sendMessage(mime, threadId) {
  const body = { raw: b64urlEncode(mime) };
  if (threadId) body.threadId = threadId;
  return api('/messages/send', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
}

/**
 * Find the draft that owns a message, and return it ready for editing.
 *
 * The Drafts mailbox is fetched by LABEL, so the app holds message ids while
 * the drafts API is keyed by DRAFT id -- and they are different. Without this
 * lookup a draft could be listed and never opened, which is exactly the state
 * the product was in.
 *
 * Returns the draft id alongside the RAW message resource. Parsing stays in
 * the worker beside extractBody, which already knows how to read a Gmail
 * payload -- a second parser is how two readers drift.
 */
async function getDraftForMessage(messageId) {
  const list = await api('/drafts?maxResults=500');
  const hit = (list.drafts || []).find((d) => d.message?.id === messageId);
  if (!hit) return null;
  const full = await api(`/drafts/${encodeURIComponent(hit.id)}?format=full`);
  return { draftId: hit.id, message: full.message || {} };
}

/** Save a draft rather than sending. */
async function saveDraft(mime, threadId, draftId) {
  const message = { raw: b64urlEncode(mime) };
  if (threadId) message.threadId = threadId;
  const payload = JSON.stringify({ message });
  if (draftId) {
    return api(`/drafts/${encodeURIComponent(draftId)}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: payload,
    });
  }
  return api('/drafts', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: payload,
  });
}

// ============================================================================
// LABELS
// ============================================================================
async function listLabels() {
  const data = await api('/labels');
  return (data.labels || [])
    .filter((l) => l.type === 'user')
    .map((l) => ({ id: l.id, name: l.name }))
    .sort((a, b) => a.name.localeCompare(b.name));
}
async function createLabel(name) {
  return api('/labels', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      name,
      labelListVisibility: 'labelShow',
      messageListVisibility: 'show',
    }),
  });
}

/**
 * Find a label by name, creating it if it does not exist.
 *
 * Gmail returns 409 for a duplicate name, and two callers racing (a snooze and
 * a wake at the same moment) will do exactly that. So a failed create falls
 * back to a re-list rather than propagating: by definition the label now
 * exists, which is all the caller wanted.
 *
 * The id is cached because this is on the path of every snooze, and the id of
 * a label never changes.
 */
const labelIdCache = new Map();
async function ensureLabel(name) {
  if (labelIdCache.has(name)) return labelIdCache.get(name);

  const existing = (await api('/labels')).labels || [];
  const hit = existing.find((l) => l.name === name);
  if (hit) {
    labelIdCache.set(name, hit.id);
    return hit.id;
  }

  try {
    const made = await createLabel(name);
    if (made?.id) {
      labelIdCache.set(name, made.id);
      return made.id;
    }
  } catch {
    // Fall through: most likely a race, and the re-list below settles it.
  }

  const after = (await api('/labels')).labels || [];
  const found = after.find((l) => l.name === name);
  if (!found) throw new Error(`Could not create the "${name}" label`);
  labelIdCache.set(name, found.id);
  return found.id;
}

/** Test seam. */
function _clearLabelCache() {
  labelIdCache.clear();
}

// ============================================================================
// ATTACHMENTS
// ============================================================================

/**
 * Fetch one attachment as a data: URL.
 *
 * Returned as a data URL rather than a blob because the worker has no DOM and
 * therefore no URL.createObjectURL. The app turns it into a download. Gmail's
 * attachment payloads are base64url, which is NOT what a data: URL wants, so
 * the padding and alphabet are converted here.
 */
async function getAttachment(messageId, attachmentId, mimeType) {
  const data = await api(
    `/messages/${encodeURIComponent(messageId)}/attachments/${encodeURIComponent(attachmentId)}`
  );
  const b64 = String(data.data || '').replace(/-/g, '+').replace(/_/g, '/');
  const padded = b64 + '='.repeat((4 - (b64.length % 4)) % 4);
  return `data:${mimeType || 'application/octet-stream'};base64,${padded}`;
}


/* ==== src/app/snooze.js =========================================== */
/**
 * Snooze.
 *
 * Hide a message until a chosen time, then put it back at the top of the
 * inbox. Gmail has this; the audit ranked it high because a student inbox is
 * full of things that matter on a specific future date and are pure noise
 * until then.
 *
 * WHY THIS IS MORE THAN "REMOVE INBOX, ADD IT BACK LATER"
 * ------------------------------------------------------
 * The obvious implementation loses mail. If the wake never fires -- extension
 * disabled, profile moved to another machine, alarm dropped by the browser --
 * the message has been removed from the inbox and nothing will ever put it
 * back. The user does not know it existed, so they cannot go looking.
 *
 * Three defences, all required:
 *
 *   1. A REAL GMAIL LABEL (`BMM/Snoozed`) carries the state, not just local
 *      storage. Wiping the extension leaves the mail findable in Gmail.
 *
 *   2. A VISIBLE SNOOZED VIEW. Nothing is ever invisible; the user can always
 *      see what they deferred and cancel it.
 *
 *   3. A CATCH-UP SWEEP ON EVERY STARTUP, not only on the alarm. Anything
 *      already overdue wakes immediately. This is what makes a missed alarm a
 *      late delivery instead of a lost message.
 *
 * The wake times are deliberately few. A date-time picker for something you
 * do fifteen times a day is friction; Gmail's fixed presets are right, and
 * "this evening / tomorrow / this weekend / next week" covers nearly all of
 * it. `untilDeadline` is ours and Gmail cannot offer it: it reads the date the
 * deadline parser already found in the message.
 */
const SNOOZE_LABEL = 'BMM/Snoozed';
const KEY = 'snoozed';

/** Round to a sensible hour, never to "now + 8h and 37 minutes". */
function at(date, hour) {
  const d = new Date(date);
  d.setHours(hour, 0, 0, 0);
  return d.getTime();
}

function startOfTomorrow(now, hour = 8) {
  const d = new Date(now);
  d.setDate(d.getDate() + 1);
  return at(d, hour);
}

/**
 * The preset wake times, resolved against `now`.
 *
 * Presets that have already passed are omitted rather than shown and quietly
 * corrected -- offering "This evening" at 11pm and silently meaning tomorrow
 * evening is the kind of small dishonesty that erodes trust in the feature.
 *
 * @param {number} now
 * @param {{deadline?:number}} ctx
 */
function presets(now = Date.now(), ctx = {}) {
  const out = [];
  const d = new Date(now);
  const hour = d.getHours();

  if (hour < 18) out.push({ id: 'evening', label: 'This evening', at: at(d, 18) });
  out.push({ id: 'tomorrow', label: 'Tomorrow morning', at: startOfTomorrow(d, 8) });

  // Saturday 8am, unless it already is the weekend.
  const day = d.getDay(); // 0 Sun .. 6 Sat
  if (day !== 6 && day !== 0) {
    const sat = new Date(d);
    sat.setDate(sat.getDate() + (6 - day));
    out.push({ id: 'weekend', label: 'This weekend', at: at(sat, 8) });
  }

  const nextMon = new Date(d);
  nextMon.setDate(nextMon.getDate() + ((8 - day) % 7 || 7));
  out.push({ id: 'nextweek', label: 'Next week', at: at(nextMon, 8) });

  /*
   * OURS, NOT GMAIL'S. The deadline parser already extracted a date from this
   * message; waking the day before it is almost always what the user means
   * when they snooze a message that has a deadline in it.
   */
  if (ctx.deadline) {
    const before = new Date(ctx.deadline);
    before.setDate(before.getDate() - 1);
    const t = at(before, 8);
    if (t > now) out.push({ id: 'deadline', label: 'Day before the deadline', at: t });
  }

  return out.filter((p) => p.at > now);
}

/** @returns {Promise<Record<string, {at:number, snoozedAt:number}>>} */
async function loadSnoozed(storage = chrome.storage.local) {
  try {
    const got = (await storage.get(KEY)) || {};
    const raw = got[KEY];
    return raw && typeof raw === 'object' ? raw : {};
  } catch {
    return {};
  }
}
async function addSnooze(id, wakeAt, storage = chrome.storage.local, now = Date.now()) {
  const all = await loadSnoozed(storage);
  all[id] = { at: wakeAt, snoozedAt: now };
  try {
    await storage.set({ [KEY]: all });
  } catch {
    return null;
  }
  return all;
}
async function removeSnooze(id, storage = chrome.storage.local) {
  const all = await loadSnoozed(storage);
  if (!(id in all)) return all;
  delete all[id];
  try {
    await storage.set({ [KEY]: all });
  } catch {
    // Best effort.
  }
  return all;
}

/**
 * Everything whose wake time has passed.
 *
 * Called on the alarm AND on every startup. The startup call is the one that
 * makes a missed alarm survivable.
 */
function due(all, now = Date.now()) {
  return Object.entries(all)
    .filter(([, v]) => v && typeof v.at === 'number' && v.at <= now)
    .map(([id]) => id);
}

/** Still asleep, soonest first -- the order the Snoozed view should show. */
function pending(all, now = Date.now()) {
  return Object.entries(all)
    .filter(([, v]) => v && typeof v.at === 'number' && v.at > now)
    .sort((a, b) => a[1].at - b[1].at)
    .map(([id, v]) => ({ id, at: v.at }));
}

/** "in 3 hours", "tomorrow", "on 14 Mar" -- the same voice as the radar. */
function wakeLabel(wakeAt, now = Date.now()) {
  const ms = wakeAt - now;
  if (ms <= 0) return 'now';
  const mins = Math.round(ms / 60000);
  if (mins < 60) return `in ${mins} min`;
  const hours = Math.round(mins / 60);
  if (hours < 24) return `in ${hours} hour${hours === 1 ? '' : 's'}`;
  const days = Math.round(hours / 24);
  if (days === 1) return 'tomorrow';
  if (days < 7) return `in ${days} days`;
  return new Date(wakeAt).toLocaleDateString(undefined, { day: 'numeric', month: 'short' });
}


/* ==== src/background/sync.js ====================================== */
/**
 * Sync orchestration.
 *
 * DESIGN: THE WORKER PULLS, THE APP DECIDES WHEN
 * ----------------------------------------------
 * The old version pushed: a background loop streamed messages into the store
 * as they arrived and every arrival re-rendered. The audit's own verdict was
 * that this was the main source of the lag.
 *
 * Here the app asks for one page at a time (`syncPage`). One page = one list
 * call + one batch call = exactly two HTTP round trips for 100 messages, and
 * on the app side exactly ONE store batch and therefore ONE render.
 *
 * The worker keeps no message state. MV3 kills the worker whenever it likes;
 * anything cached in a module variable here would be a heisenbug. The only
 * persisted thing is `historyId`, and that lives in chrome.storage.
 */

const HISTORY_KEY = 'historyId';
async function getHistoryId() {
  const { [HISTORY_KEY]: id } = await chrome.storage.local.get(HISTORY_KEY);
  return id || null;
}
async function setHistoryId(id) {
  if (id) await chrome.storage.local.set({ [HISTORY_KEY]: String(id) });
}

/**
 * One page of the inbox, fully hydrated.
 *
 * @param {{pageToken?:string, max?:number, q?:string, labelIds?:string[]}} opts
 * @returns {Promise<{messages:object[], nextPageToken:string}>}
 */
async function syncPage({ pageToken = '', max = BATCH_SIZE, q = '', labelIds, anchorHistory = true } = {}) {
  // Read the cursor BEFORE listing, on the first page of a fresh sync.
  //
  // This used to be read AFTER the messages were fetched, which loses mail:
  //
  //   t0  listIds()        -> the inbox as it is now
  //   t1  batchMetadata()  -> hydrate exactly those ids
  //   t2  profile()        -> historyId as of t2
  //
  // Anything that arrived between t0 and t2 is absent from our list, yet the
  // stored cursor already covers it, so the next delta reports no change for
  // it. That message stays invisible until the cursor expires, about a week.
  //
  // Taking the cursor first inverts the failure: it can only be slightly
  // STALE, so the next delta replays a handful of changes we already have.
  // `upsert` is idempotent, so a replay costs nothing. Stale loses nothing;
  // too-new loses mail irrecoverably.
  /*
   * ONLY THE INBOX MOVES THE CURSOR.
   *
   * The historyId is a single account-wide cursor that the inbox's delta sync
   * depends on. Loading a page of Sent or Trash would otherwise advance it
   * past inbox changes that were never fetched, and those changes are then
   * unrecoverable -- exactly the bug fixed above, reintroduced through a
   * different door. Non-inbox mailboxes pass `anchorHistory: false`.
   */
  let anchor = null;
  if (anchorHistory && !pageToken) {
    try {
      anchor = (await profile()).historyId;
    } catch {
      /* a missing cursor only costs a full resync later */
    }
  }

  const { ids, nextPageToken } = await listIds({
    pageToken,
    max: Math.min(max, BATCH_SIZE),
    q,
    labelIds: labelIds || (q ? [] : ['INBOX']),
  });
  if (ids.length === 0) {
    if (anchor) await setHistoryId(anchor);
    return { messages: [], nextPageToken: '' };
  }

  const messages = await batchMetadata(ids);
  if (anchor) await setHistoryId(anchor);
  return { messages, nextPageToken };
}

/**
 * Delta sync since the stored cursor.
 *
 * Returns one of:
 *   { kind: 'delta', added:[msg], removed:[id], patched:[{id,unread,starred}] }
 *   { kind: 'resync' }   -- cursor expired, caller must do a full syncPage run
 *   { kind: 'none' }     -- no cursor yet
 */
/**
 * Beyond this many new messages in one delta, a full resync is both cheaper
 * and safer than a very long chain of batch requests.
 */
const MAX_DELTA_ADDS = 500;
async function syncDelta() {
  const start = await getHistoryId();
  if (!start) return { kind: 'none' };

  const res = await history(start);
  if (res.tooOld) {
    await chrome.storage.local.remove(HISTORY_KEY);
    return { kind: 'resync' };
  }

  const { addIds, removeIds, patched } = reduceHistory(res.changes);

  if (addIds.length > MAX_DELTA_ADDS) {
    // Do NOT advance the cursor: the resync is what will cover these.
    return { kind: 'resync' };
  }

  // Chunked, not truncated. BATCH_SIZE is Gmail's cap on one /batch request,
  // not a cap on how much mail can arrive between two syncs.
  const added = [];
  for (let i = 0; i < addIds.length; i += BATCH_SIZE) {
    added.push(...(await batchMetadata(addIds.slice(i, i + BATCH_SIZE))));
  }

  // Only now, after every page was read and every add was fetched.
  await setHistoryId(res.historyId);

  return { kind: 'delta', added, removed: removeIds, patched };
}

/**
 * Fold a list of history records into a final state per message.
 *
 * WHY A SINGLE ORDERED MAP AND NOT TWO SETS
 * -----------------------------------------
 * History records are chronological and one message can appear in many of
 * them: arrive, get starred, get archived, get un-archived. The first version
 * of this function accumulated an `added` set and a `removed` set
 * independently, which meant a message that was archived and then un-archived
 * ended up in BOTH, and the caller's apply order silently decided whether the
 * message survived.
 *
 * What the API actually gives us is a sequence of events. Only the last event
 * per message matters. Writing them into one map in order makes that true by
 * construction, and guarantees the returned `added` and `removed` are
 * disjoint -- so the caller cannot get it wrong either.
 *
 * Exported for testing; this is the part with all the ordering subtlety.
 */
function reduceHistory(records) {
  /** @type {Map<string, 'add'|'remove'>} id -> final presence in our inbox */
  const fate = new Map();
  /** @type {Map<string, {id:string, unread?:boolean, starred?:boolean}>} */
  const patches = new Map();

  const patchFor = (id) => {
    let p = patches.get(id);
    if (!p) patches.set(id, (p = { id }));
    return p;
  };

  for (const h of records || []) {
    for (const { message } of h.messagesAdded || []) {
      // A brand-new message. Only interesting if it landed in the inbox.
      if ((message.labelIds || []).includes('INBOX')) fate.set(message.id, 'add');
    }

    for (const { message } of h.messagesDeleted || []) {
      fate.set(message.id, 'remove');
    }

    for (const { message, labelIds } of h.labelsAdded || []) {
      const ls = labelIds || [];
      if (ls.includes('UNREAD')) patchFor(message.id).unread = true;
      if (ls.includes('STARRED')) patchFor(message.id).starred = true;
      // Gaining INBOX means un-archived, or a thread pulled back by a reply.
      // This never produces a messagesAdded record -- that fires only when a
      // message first enters the mailbox -- so if we ignore it here the message
      // stays invisible until the next full resync.
      if (ls.includes('INBOX')) fate.set(message.id, 'add');
      if (ls.includes('TRASH') || ls.includes('SPAM')) fate.set(message.id, 'remove');
    }

    for (const { message, labelIds } of h.labelsRemoved || []) {
      const ls = labelIds || [];
      if (ls.includes('UNREAD')) patchFor(message.id).unread = false;
      if (ls.includes('STARRED')) patchFor(message.id).starred = false;
      // Losing INBOX is an archive.
      if (ls.includes('INBOX')) fate.set(message.id, 'remove');
    }
  }

  const addIds = [];
  const removeIds = [];
  for (const [id, what] of fate) (what === 'add' ? addIds : removeIds).push(id);

  // A message we are about to fetch fresh does not need a patch -- the fetched
  // metadata is newer. A message we are about to remove cannot use one.
  const skip = new Set([...addIds, ...removeIds]);
  const patched = [];
  for (const p of patches.values()) {
    if (skip.has(p.id)) continue;
    if ('unread' in p || 'starred' in p) patched.push(p);
  }

  return { addIds, removeIds, patched };
}


/* ==== src/background/index.js ===================================== */
/**
 * Service worker.
 *
 * Deliberately thin. In MV3 the worker is killed aggressively, so anything
 * stateful here is a bug waiting to happen. Its jobs:
 *   - route the toolbar click / keyboard shortcut into the Gmail tab
 *   - own OAuth (the app iframe never sees a token)
 *   - proxy Gmail API calls
 */





/**
 * Inline-image budget. See GET_INLINE.
 *
 * 2MB of source bytes becomes roughly 2.7MB of base64 in the srcdoc string,
 * which is a large but survivable document. 20 parts covers every legitimate
 * newsletter seen in the data pack with room to spare.
 */
const MAX_INLINE_BYTES = 2 * 1024 * 1024;
const MAX_INLINE_PARTS = 20;

/**
 * Is this a Gmail tab?
 *
 * `tab.url` is only populated when the extension holds either the broad `tabs`
 * permission or a host permission for that specific tab. We hold the host
 * permission for mail.google.com, which is the narrower of the two -- `tabs`
 * would expose the URL of EVERY tab the user has open.
 *
 * This being undefined is what broke the toolbar button: the check fell
 * through to the "not on Gmail" branch and opened a new tab on every click.
 */
function isGmail(tab) {
  return typeof tab?.url === 'string' && tab.url.startsWith('https://mail.google.com/');
}

/**
 * Startup self-check.
 *
 * Every one of the three bugs that made the first real browser run fail was a
 * manifest/code mismatch that produced SILENCE rather than an error: a missing
 * host permission left tab.url undefined, a missing `scripting` permission
 * made the injection path throw into an empty catch, and a shortcut that
 * collided with the browser's own was simply never delivered. None of it
 * appeared anywhere a user would look.
 *
 * This logs the actual granted state once at startup, so the next mismatch is
 * one glance at the service worker console instead of a debugging session.
 */
chrome.runtime.onInstalled?.addListener(async () => {
  const manifest = chrome.runtime.getManifest();
  const problems = [];

  if (!chrome.scripting) problems.push('chrome.scripting unavailable -- "scripting" permission missing');
  if (!(manifest.host_permissions || []).some((h) => h.includes('mail.google.com'))) {
    problems.push('no host permission for mail.google.com -- tab.url will be undefined');
  }

  const commands = await chrome.commands.getAll().catch(() => []);
  for (const c of commands) {
    // An empty shortcut means the browser refused it, usually a collision.
    if (c.name === 'toggle-takeover' && !c.shortcut) {
      problems.push(
        'the keyboard shortcut is unassigned -- set one at chrome://extensions/shortcuts'
      );
    }
  }

  if (problems.length) {
    console.warn('[BMM] startup problems:\n  - ' + problems.join('\n  - '));
  } else {
    console.info('[BMM] ready. Shortcut:', commands.find((c) => c.name === 'toggle-takeover')?.shortcut || '(none)');
  }
});

/*
 * Toolbar click: tell the content script in THIS tab to toggle.
 *
 * WHY THIS IS OPTIONAL-CHAINED, when the manifest declares `action`.
 *
 * A top-level `chrome.action.onClicked.addListener(...)` throws a TypeError
 * during module evaluation if `chrome.action` is undefined -- and that aborts
 * the WHOLE service worker. Chrome reports it as
 * "Service worker registration failed. Status code: 2", which names no file,
 * no line and no cause.
 *
 * `chrome.action` is undefined whenever the manifest's `action` key is absent
 * or malformed, which is easy to do by hand-editing and impossible to
 * diagnose from the error. The cost of one `?.` is nothing; the cost of the
 * unguarded form is an extension that appears completely dead. Every other
 * capability here already degrades rather than crashing -- see the alarms
 * block below, which has been guarded from the start.
 */
chrome.action?.onClicked.addListener(async (tab) => {
  if (!tab?.id) return;

  if (isGmail(tab)) {
    await toggleIn(tab.id);
    return;
  }

  // Not on Gmail. Prefer an existing Gmail tab over opening another one --
  // repeatedly spawning tabs is what the old behaviour did, and each new tab
  // resolved to the browser's default account rather than the one the user was
  // already reading.
  const [existing] = await chrome.tabs.query({ url: 'https://mail.google.com/*' });
  if (existing?.id) {
    await chrome.tabs.update(existing.id, { active: true });
    if (existing.windowId != null) {
      await chrome.windows.update(existing.windowId, { focused: true }).catch(() => {});
    }
    await toggleIn(existing.id);
    return;
  }

  // Genuinely no Gmail tab open. Opening the bare URL sends the user to
  // whichever account Chrome considers default, so this is a last resort.
  await chrome.tabs.create({ url: 'https://mail.google.com/' });
});

// Same reasoning as chrome.action above: a missing `commands` key must cost
// the shortcut, not the entire worker.
chrome.commands?.onCommand.addListener(async (command) => {
  if (command !== 'toggle-takeover') return;
  const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
  if (isGmail(tab) && tab.id) await toggleIn(tab.id);
});

/**
 * Send the toggle, injecting the content script first if it is not there.
 *
 * The injection path matters more than it looks: a content script declared in
 * the manifest is only present in tabs loaded AFTER the extension was
 * installed or reloaded. Without this, the button does nothing at all on every
 * Gmail tab that was already open -- which is the common case immediately
 * after installing.
 */
async function toggleIn(tabId) {
  try {
    await chrome.tabs.sendMessage(tabId, { type: 'BMM_TOGGLE' });
    return;
  } catch {
    // No receiver. Fall through and inject.
  }

  try {
    await chrome.scripting.insertCSS({
      target: { tabId },
      files: ['src/takeover/takeover.css'],
    });
    await chrome.scripting.executeScript({
      target: { tabId },
      files: ['src/takeover/content.js'],
    });
    await chrome.tabs.sendMessage(tabId, { type: 'BMM_TOGGLE' });
  } catch (err) {
    // Previously this whole path was swallowed by `.catch(() => {})`, so a
    // missing `scripting` permission looked exactly like success and the
    // button silently did nothing. Surface it instead.
    console.error('[BMM] could not start the takeover:', err);
    await chrome.action.setBadgeText({ tabId, text: '!' }).catch(() => {});
    await chrome.action.setBadgeBackgroundColor({ tabId, color: '#c0392b' }).catch(() => {});
  }
}

/**
 * Message router for the app iframe.
 *
 * The app never holds an access token. It asks the worker, the worker calls
 * Gmail. That keeps the token out of a document that renders untrusted mail.
 */
chrome.runtime.onMessage.addListener((msg, _sender, sendResponse) => {
  handle(msg)
    .then((data) => sendResponse({ ok: true, data }))
    .catch((err) => sendResponse({ ok: false, error: String(err?.message || err) }));
  return true; // keep the channel open for the async reply
});

async function handle(msg) {
  switch (msg?.type) {
    case 'AUTH_STATUS':
      return { signedIn: await isSignedIn() };
    case 'SIGN_IN':
      await signIn();
      return { signedIn: true };
    case 'SIGN_OUT':
      await signOut();
      return { signedIn: false };
    case 'PROFILE':
      return profile();

    // ---- sync ----------------------------------------------------------
    case 'SYNC_PAGE': {
      const opts = { ...(msg.opts || {}) };
      // A mailbox identified by label NAME (our snoozed label) has to be
      // resolved to an id before listing; Gmail's list API takes ids only.
      if (opts.labelName) {
        try {
          opts.labelIds = [await ensureLabel(opts.labelName)];
        } catch {
          // The label does not exist yet, which simply means nothing has ever
          // been put in it. An empty page is the honest answer.
          return { messages: [], nextPageToken: '' };
        }
        delete opts.labelName;
      }
      return syncPage(opts);
    }
    case 'SYNC_DELTA':
      return syncDelta();

    // ---- reading -------------------------------------------------------
    case 'GET_BODY':
      return extractBody(await getFull(msg.id));

    // ---- triage --------------------------------------------------------
    // Every one of these is fire-and-await from the app, but the app has
    // ALREADY applied the change optimistically. Gmail round trips are
    // 200-600ms; making the UI wait for them is what made the old version
    // feel dead on click.
    case 'MARK_READ':
      return modify(msg.id, [], ['UNREAD']);
    case 'MARK_UNREAD':
      return modify(msg.id, ['UNREAD'], []);
    case 'STAR':
      return modify(msg.id, msg.on ? ['STARRED'] : [], msg.on ? [] : ['STARRED']);
    case 'ARCHIVE':
      return modify(msg.id, [], ['INBOX']);
    case 'TRASH':
      return trash(msg.id);
    case 'BULK':
      return batchModify(msg.ids, msg.add || [], msg.remove || []);
    case 'UNARCHIVE':
      // The inverse of archive, for undo. Gmail has no such button.
      return modify(msg.id, ['INBOX'], []);
    case 'UNTRASH':
      return api(`/messages/${encodeURIComponent(msg.id)}/untrash`, { method: 'POST' });

    /*
     * SPAM. Core mail triage that was missing entirely: you could BROWSE the
     * spam mailbox but not report a message into it, and not rescue one out.
     *
     * Reporting removes INBOX as well as adding SPAM. Gmail's own UI does the
     * same -- a message left in both places shows up in the inbox while
     * claiming to be spam, which is the worst of both.
     *
     * Rescuing restores INBOX, because a false positive you have to go and
     * re-file by hand is only half a rescue.
     */
    case 'SPAM':
      return modify(msg.id, ['SPAM'], ['INBOX']);
    case 'NOT_SPAM':
      return modify(msg.id, ['INBOX'], ['SPAM']);

    // ---- compose ---------------------------------------------------------
    case 'SEND':
      return sendMessage(buildMime(msg.draft), msg.draft.threadId);
    /*
     * Open a draft for editing. The Drafts mailbox is fetched by label, so the
     * app has a MESSAGE id and the drafts API wants a DRAFT id -- see
     * getDraftForMessage. Without this a draft could be listed and never
     * opened, which is where the product was.
     */
    case 'GET_DRAFT': {
      const d = await getDraftForMessage(msg.id);
      if (!d) return null;
      // Parsed HERE, beside extractBody, which already knows how to read a
      // Gmail payload. A second parser is how two readers drift apart.
      return { draftId: d.draftId, ...extractBody(d.message) };
    }
    case 'SAVE_DRAFT':
      return saveDraft(buildMime(msg.draft), msg.draft.threadId, msg.draftId);

    // ---- labels ----------------------------------------------------------
    case 'LIST_LABELS':
      return listLabels();
    case 'CREATE_LABEL':
      return createLabel(msg.name);

    // ---- snooze ----------------------------------------------------------
    /*
     * Snoozing is two Gmail mutations in one step: out of the inbox, into the
     * snoozed label. Doing them as one `modify` call means there is no window
     * where the message is in neither place.
     */
    case 'SNOOZE': {
      const labelId = await ensureLabel(SNOOZE_LABEL);
      await modify(msg.id, [labelId], ['INBOX']);
      await scheduleWake();
      return { ok: true };
    }
    case 'UNSNOOZE': {
      const labelId = await ensureLabel(SNOOZE_LABEL);
      // Back to the inbox and unread, because a message that reappears
      // already-read will be scrolled past and never seen.
      await modify(msg.id, ['INBOX', 'UNREAD'], [labelId]);
      return { ok: true };
    }
    case 'WAKE_DUE':
      return { woke: await wakeDue() };

    // ---- attachments -----------------------------------------------------
    case 'GET_ATTACHMENT':
      return { dataUrl: await getAttachment(msg.messageId, msg.attachmentId, msg.mimeType) };

    /*
     * Inline images for one message, resolved in a single round trip.
     *
     * BOUNDED. A message can legitimately carry a dozen inline images, and a
     * hostile one can claim a hundred. Every resolved part is inlined into the
     * srcdoc as base64, which costs ~1.37x its byte size in the string, so an
     * unbounded fetch here is a memory and paint problem, not just a network
     * one. Oversized parts are skipped and render as placeholders.
     */
    case 'GET_INLINE': {
      const parts = Array.isArray(msg.parts) ? msg.parts.slice(0, MAX_INLINE_PARTS) : [];
      const out = [];
      let budget = MAX_INLINE_BYTES;
      for (const p of parts) {
        if (!p?.attachmentId || !p?.contentId) continue;
        if ((p.size || 0) > budget) continue;
        try {
          const dataUrl = await getAttachment(msg.messageId, p.attachmentId, p.mimeType);
          budget -= p.size || 0;
          out.push({ contentId: p.contentId, filename: p.filename || '', dataUrl });
        } catch {
          // One unfetchable part must not blank the whole message body.
        }
      }
      return { inline: out };
    }

    default:
      throw new Error(`Unknown message: ${msg?.type}`);
  }
}


/**
 * Pull a displayable body out of Gmail's MIME tree.
 *
 * Done in the WORKER, not in the app document, for one reason: the worker has
 * no DOM, so a malicious body cannot do anything here no matter how it is
 * shaped. The app receives inert strings and renders them into a sandboxed
 * iframe with no allow-scripts.
 *
 * Gmail nests parts arbitrarily deep (multipart/mixed > multipart/alternative
 * > text/html). The old version only looked one level down and therefore
 * showed "(no content)" for any mail with an attachment.
 */
function extractBody(full) {
  // Headers needed to REPLY correctly, not just to display.
  //
  // Without Message-ID and References a reply arrives as a brand-new
  // conversation in the recipient's client -- the single most visible way a
  // mail client looks broken, and invisible to the person sending it.
  const h = headerMap(full.payload?.headers);

  const out = {
    id: full.id,
    threadId: full.threadId,
    html: '',
    text: '',
    attachments: [],
    // Inline parts referenced by the HTML as `cid:`. Kept separate from
    // `attachments` so they do not appear as download chips: they are part of
    // the message body, not things the user attached.
    inline: [],
    // For threading and for pre-filling reply-all.
    messageId: h['message-id'] || '',
    references: h.references || '',
    from: h.from || '',
    to: h.to || '',
    cc: h.cc || '',
    replyTo: h['reply-to'] || '',
    subject: h.subject || '',
    // internalDate is authoritative; the Date: header is sender-controlled and
    // routinely wrong. Needed for the reply attribution line.
    date: Number(full.internalDate) || Date.parse(h.date) || 0,
    listUnsubscribe: h['list-unsubscribe'] || '',
  };
  walk(full.payload);
  return out;

  function walk(part) {
    if (!part) return;
    const mime = part.mimeType || '';
    const filename = part.filename || '';

    /*
     * INLINE vs ATTACHED.
     *
     * A part is inline when it carries a Content-ID that the HTML references,
     * or when it is explicitly `Content-Disposition: inline`. Those must NOT
     * become download chips -- a signature logo listed as an attachment is
     * noise, and it is why some clients show "3 attachments" on a message that
     * visibly has none.
     */
    const ph = headerMap(part.headers);
    const contentId = (ph['content-id'] || '').trim().replace(/^<|>$/g, '');
    const disposition = (ph['content-disposition'] || '').toLowerCase();
    const isInline = mime.startsWith('image/') &&
      (!!contentId || disposition.startsWith('inline'));

    if (isInline && part.body?.attachmentId) {
      out.inline.push({
        contentId,
        filename,
        mimeType: mime,
        size: part.body.size || 0,
        attachmentId: part.body.attachmentId,
      });
    } else if (filename && part.body?.attachmentId) {
      out.attachments.push({
        filename,
        mimeType: mime,
        size: part.body.size || 0,
        attachmentId: part.body.attachmentId,
      });
    } else if (mime === 'text/html' && part.body?.data && !out.html) {
      out.html = b64url(part.body.data);
    } else if (mime === 'text/plain' && part.body?.data && !out.text) {
      out.text = b64url(part.body.data);
    }
    for (const child of part.parts || []) walk(child);
  }
}

/** Gmail returns base64url with no padding. atob wants base64 with padding. */
function b64url(data) {
  const b64 = data.replace(/-/g, '+').replace(/_/g, '/');
  const padded = b64 + '='.repeat((4 - (b64.length % 4)) % 4);
  try {
    // Round-trip through bytes so UTF-8 (e.g. curly quotes, INR) survives.
    const bin = atob(padded);
    const bytes = Uint8Array.from(bin, (c) => c.charCodeAt(0));
    return new TextDecoder('utf-8').decode(bytes);
  } catch {
    return '';
  }
}

// ============================================================================
// SNOOZE WAKE
// ============================================================================

/**
 * Waking snoozed mail.
 *
 * MV3 SERVICE WORKERS ARE KILLED AGGRESSIVELY, so a `setTimeout` for
 * "tomorrow at 8am" does not survive: the worker is gone within seconds of
 * going idle. `chrome.alarms` is the only timer that persists, and its
 * minimum granularity is one minute.
 *
 * The alarm is therefore a NUDGE, not a guarantee. The real correctness comes
 * from `wakeDue()` being run on startup and on install as well: anything
 * overdue is delivered late rather than lost. A snooze that silently eats
 * mail is worse than no snooze at all.
 */
const WAKE_ALARM = 'bmm-wake';

async function wakeDue(now = Date.now()) {
  let all;
  try {
    all = await loadSnoozed(chrome.storage.local);
  } catch {
    return 0;
  }

  const ready = due(all, now);
  if (!ready.length) return 0;

  let labelId;
  try {
    labelId = await ensureLabel(SNOOZE_LABEL);
  } catch {
    // Not signed in, or offline. Leave the entries alone so the next sweep
    // retries; dropping them here is how mail goes missing.
    return 0;
  }

  let woke = 0;
  for (const id of ready) {
    try {
      await modify(id, ['INBOX', 'UNREAD'], [labelId]);
      await removeSnooze(id, chrome.storage.local);
      woke++;
    } catch {
      // One failure must not stop the rest, and the entry stays put so the
      // next sweep tries again.
    }
  }
  return woke;
}

/**
 * Point the alarm at the NEXT wake time.
 *
 * One alarm, re-aimed, rather than one alarm per snoozed message: alarms are a
 * shared, limited resource and a hundred snoozed messages should not mean a
 * hundred registrations.
 */
async function scheduleWake() {
  if (!chrome.alarms) return;
  const all = await loadSnoozed(chrome.storage.local);
  const times = Object.values(all)
    .map((v) => v?.at)
    .filter((t) => typeof t === 'number');
  if (!times.length) {
    await chrome.alarms.clear(WAKE_ALARM);
    return;
  }
  const next = Math.min(...times);
  // Never schedule in the past; Chrome fires those immediately and repeatedly.
  await chrome.alarms.create(WAKE_ALARM, { when: Math.max(next, Date.now() + 5000) });
}

if (chrome.alarms?.onAlarm) {
  chrome.alarms.onAlarm.addListener(async (alarm) => {
    if (alarm.name !== WAKE_ALARM) return;
    await wakeDue();
    await scheduleWake(); // re-aim at whatever is next
  });
}

// The catch-up sweep. Both hooks, because onStartup does not fire when the
// extension is enabled mid-session or reloaded during development.
chrome.runtime.onStartup?.addListener(() => { wakeDue().then(scheduleWake); });
chrome.runtime.onInstalled?.addListener(() => { wakeDue().then(scheduleWake); });

